changeSet.sql:
ALTER TABLE api_keys
    ADD COLUMN expires_at TIMESTAMPTZ NULL;
ALTER TABLE api_keys
    ADD COLUMN parent_api_key_id INTEGER NULL
        REFERENCES api_keys(id) ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_api_keys_expires_at
    ON api_keys (expires_at)
    WHERE expires_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_api_keys_parent
    ON api_keys (parent_api_key_id)
    WHERE parent_api_key_id IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS idx_api_keys_parent;
DROP INDEX IF EXISTS idx_api_keys_expires_at;
ALTER TABLE api_keys DROP COLUMN IF EXISTS parent_api_key_id;
ALTER TABLE api_keys DROP COLUMN IF EXISTS expires_at;

changeSet.sql:
ALTER TABLE agent_sessions
    ADD COLUMN session_api_key_id INTEGER NULL
        REFERENCES api_keys(id) ON DELETE SET NULL;
